/*
 * linux/include/linux/ppdev.h
 *
 * User-space parallel port device driver (header file).
 *
 * Copyright (C) 1998-9 Tim Waugh <tim@cyberelk.demon.co.uk>
 *
 * This program is free software; you can redistribute it and/or
 * modify it under the terms of the GNU General Public License
 * as published by the Free Software Foundation; either version
 * 2 of the License, or (at your option) any later version.
 *
 * Added PPGETTIME/PPSETTIME, Fred Barnes, 1999
 * Added PPGETMODES/PPGETMODE/PPGETPHASE, Fred Barnes <frmb2@ukc.ac.uk>, 03/01/2001
 */

#ifndef _LINUX_PPDEV_H
#define _LINUX_PPDEV_H

#define PP_IOCTL	'p'

/* Set mode for read/write (e.g. IEEE1284_MODE_EPP) */
#define PPSETMODE	_IOW(PP_IOCTL, 0x80, int)

/* Read status */
#define PPRSTATUS	_IOR(PP_IOCTL, 0x81, unsigned char)
#define PPWSTATUS	OBSOLETE__IOW(PP_IOCTL, 0x82, unsigned char)

/* Read/write control */
#define PPRCONTROL	_IOR(PP_IOCTL, 0x83, unsigned char)
#define PPWCONTROL	_IOW(PP_IOCTL, 0x84, unsigned char)

struct ppdev_frob_struct {
	unsigned char mask;
	unsigned char val;
};
#define PPFCONTROL      _IOW(PP_IOCTL, 0x8e, struct ppdev_frob_struct)

/* Read/write data */
#define PPRDATA		_IOR(PP_IOCTL, 0x85, unsigned char)
#define PPWDATA		_IOW(PP_IOCTL, 0x86, unsigned char)

/* Read/write econtrol (not used) */
#define PPRECONTROL	OBSOLETE__IOR(PP_IOCTL, 0x87, unsigned char)
#define PPWECONTROL	OBSOLETE__IOW(PP_IOCTL, 0x88, unsigned char)

/* Read/write FIFO (not used) */
#define PPRFIFO		OBSOLETE__IOR(PP_IOCTL, 0x89, unsigned char)
#define PPWFIFO		OBSOLETE__IOW(PP_IOCTL, 0x8a, unsigned char)

/* Claim the port to start using it */
#define PPCLAIM		_IO(PP_IOCTL, 0x8b)

/* Release the port when you aren't using it */
#define PPRELEASE	_IO(PP_IOCTL, 0x8c)

/* Yield the port (release it if another driver is waiting,
 * then reclaim) */
#define PPYIELD		_IO(PP_IOCTL, 0x8d)

/* Register device exclusively (must be before PPCLAIM). */
#define PPEXCL		_IO(PP_IOCTL, 0x8f)

/* Data line direction: non-zero for input mode. */
#define PPDATADIR	_IOW(PP_IOCTL, 0x90, int)

/* Negotiate a particular IEEE 1284 mode. */
#define PPNEGOT		_IOW(PP_IOCTL, 0x91, int)

/* Set control lines when an interrupt occurs. */
#define PPWCTLONIRQ	_IOW(PP_IOCTL, 0x92, unsigned char)

/* Clear (and return) interrupt count. */
#define PPCLRIRQ	_IOR(PP_IOCTL, 0x93, int)

/* Set the IEEE 1284 phase that we're in (e.g. IEEE1284_PH_FWD_IDLE) */
#define PPSETPHASE	_IOW(PP_IOCTL, 0x94, int)

/* Set and get port timeout (struct timeval's) */
#define PPGETTIME	_IOR(PP_IOCTL, 0x95, struct timeval)
#define PPSETTIME	_IOW(PP_IOCTL, 0x96, struct timeval)

/* Get available modes (what the hardware can do) */
#define PPGETMODES	_IOR(PP_IOCTL, 0x97, unsigned int)

/* Get the current mode and phaze */
#define PPGETMODE	_IOR(PP_IOCTL, 0x98, int)
#define PPGETPHASE	_IOR(PP_IOCTL, 0x99, int)

/* get/set flags */
#define PPGETFLAGS	_IOR(PP_IOCTL, 0x9a, int)
#define PPSETFLAGS	_IOW(PP_IOCTL, 0x9b, int)

/* flags visible to the world */
#define PP_FASTWRITE	(1<<2)
#define PP_FASTREAD	(1<<3)
#define PP_W91284PIC	(1<<4)

/* only masks user-visible flags */
#define PP_FLAGMASK	(PP_FASTWRITE | PP_FASTREAD | PP_W91284PIC)

#endif /* _LINUX_PPDEV_H */

input.prompt:
I need to compute the Linux ioctl numbers for ppdev ioctls on amd64 and 386. Write a C program, compile it, and run it to print the values. The program should compute:

```c
#include <stdio.h>
#include <sys/ioctl.h>
#include <linux/ppdev.h>
#include <linux/parport.h>
#include <sys/time.h>

int main() {
    printf("PPSETMODE = 0x%lx\n", (unsigned long)PPSETMODE);
    printf("PPRSTATUS = 0x%lx\n", (unsigned long)PPRSTATUS);
    printf("PPRCONTROL = 0x%lx\n", (unsigned long)PPRCONTROL);
    printf("PPWCONTROL = 0x%lx\n", (unsigned long)PPWCONTROL);
    printf("PPFCONTROL = 0x%lx\n", (unsigned long)PPFCONTROL);
    printf("PPRDATA = 0x%lx\n", (unsigned long)PPRDATA);
    printf("PPWDATA = 0x%lx\n", (unsigned long)PPWDATA);
    printf("PPCLAIM = 0x%lx\n", (unsigned long)PPCLAIM);
    printf("PPRELEASE = 0x%lx\n", (unsigned long)PPRELEASE);
    printf("PPYIELD = 0x%lx\n", (unsigned long)PPYIELD);
    printf("PPEXCL = 0x%lx\n", (unsigned long)PPEXCL);
    printf("PPDATADIR = 0x%lx\n", (unsigned long)PPDATADIR);
    printf("PPNEGOT = 0x%lx\n", (unsigned long)PPNEGOT);
    printf("PPWCTLONIRQ = 0x%lx\n", (unsigned long)PPWCTLONIRQ);
    printf("PPCLRIRQ = 0x%lx\n", (unsigned long)PPCLRIRQ);
    printf("PPSETPHASE = 0x%lx\n", (unsigned long)PPSETPHASE);
    printf("PPGETTIME = 0x%lx\n", (unsigned long)PPGETTIME);
    printf("PPSETTIME = 0x%lx\n", (unsigned long)PPSETTIME);
    printf("PPGETMODES = 0x%lx\n", (unsigned long)PPGETMODES);
    printf("PPGETMODE = 0x%lx\n", (unsigned long)PPGETMODE);
    printf("PPGETPHASE = 0x%lx\n", (unsigned long)PPGETPHASE);
    printf("PPGETFLAGS = 0x%lx\n", (unsigned long)PPGETFLAGS);
    printf("PPSETFLAGS = 0x%lx\n", (unsigned long)PPSETFLAGS);

    // Flag values
    printf("\nPP_FASTWRITE = 0x%x\n", PP_FASTWRITE);
    printf("PP_FASTREAD = 0x%x\n", PP_FASTREAD);
    printf("PP_W91284PIC = 0x%x\n", PP_W91284PIC);

    // IEEE1284 mode values
    printf("\nIEEE1284_MODE_NIBBLE = 0x%x\n", IEEE1284_MODE_NIBBLE);
    printf("IEEE1284_MODE_BYTE = 0x%x\n", IEEE1284_MODE_BYTE);
    printf("IEEE1284_MODE_COMPAT = 0x%x\n", IEEE1284_MODE_COMPAT);
    printf("IEEE1284_MODE_BECP = 0x%x\n", IEEE1284_MODE_BECP);
    printf("IEEE1284_MODE_ECP = 0x%x\n", IEEE1284_MODE_ECP);
    printf("IEEE1284_MODE_ECPRLE = 0x%x\n", IEEE1284_MODE_ECPRLE);
    printf("IEEE1284_MODE_ECPSWE = 0x%x\n", IEEE1284_MODE_ECPSWE);
    printf("IEEE1284_MODE_EPP = 0x%x\n", IEEE1284_MODE_EPP);
    printf("IEEE1284_MODE_EPPSL = 0x%x\n", IEEE1284_MODE_EPPSL);
    printf("IEEE1284_MODE_EPPSWE = 0x%x\n", IEEE1284_MODE_EPPSWE);
    printf("IEEE1284_DEVICEID = 0x%x\n", IEEE1284_DEVICEID);
    printf("IEEE1284_EXT_LINK = 0x%x\n", IEEE1284_EXT_LINK);
    printf("IEEE1284_ADDR = 0x%x\n", IEEE1284_ADDR);
    printf("IEEE1284_DATA = 0x%x\n", IEEE1284_DATA);

    // Sizes
    printf("\nsizeof(struct timeval) = %lu\n", sizeof(struct timeval));
    printf("sizeof(int) = %lu\n", sizeof(int));
    printf("sizeof(unsigned int) = %lu\n", sizeof(unsigned int));
    printf("sizeof(unsigned char) = %lu\n", sizeof(unsigned char));
    printf("sizeof(struct ppdev_frob_struct) = %lu\n", sizeof(struct ppdev_frob_struct));

    return 0;
}
```

Save it to /tmp/ppdev_ioctl.c, compile with `gcc -o /tmp/ppdev_ioctl /tmp/ppdev_ioctl.c`, and run it. Also compile with `-m32` flag and run to get 32-bit values: `gcc -m32 -o /tmp/ppdev_ioctl32 /tmp/ppdev_ioctl.c` and run that too. Report ALL output.

